SELECT ,
FROM ams_technician_info t LEFT JOIN sys_user u ON t.user_id = u.id WHERE t.user_id IN
#{id}

SELECT ,
FROM ams_technician_info t LEFT JOIN sys_user u ON t.user_id = u.id
AND u.store_id = #{storeId}
AND t.status = #{status}
AND (t.real_name LIKE CONCAT('%', #{name}, '%') OR u.nickname LIKE CONCAT('%', #{name}, '%'))
ORDER BY (t.status = 'IDLE') DESC, t.last_job_end_time ASC, t.wheel_seq ASC, t.user_id ASC

